-- Generated by scripts/generateSeedSqlGreetings.js from scripts/courseContent/greetings.js.
-- Run once in the Supabase SQL Editor, after supabase/schema.sql.
-- Regenerate + re-run any time the content file changes (upserts are idempotent).

-- The old single 'greetings' subject was split into 'greetings-hello' and
-- 'greetings-names' — clean up the old subject id and its lessons.
delete from public.course_lessons where subject_id = $q$greetings$q$;
delete from public.course_subjects where id = $q$greetings$q$;

on conflict (id) do update set
  title = excluded.title, roman = excluded.roman, description = excluded.description, sort_order = excluded.sort_order;

delete from public.course_lessons where subject_id = $q$greetings-hello$q$ and id not in ($q$gh01$q$, $q$gh02$q$, $q$gh03$q$, $q$gh04$q$, $q$gh05$q$, $q$gh06$q$, $q$gh07$q$, $q$gh08$q$);
delete from public.course_lessons where subject_id = $q$greetings-names$q$ and id not in ($q$gn01$q$, $q$gn02$q$, $q$gn03$q$, $q$gn04$q$, $q$gn05$q$, $q$gn06$q$, $q$gn07$q$);

on conflict (id) do update set
  subject_id = excluded.subject_id, sort_order = excluded.sort_order, title = excluded.title, steps = excluded.steps;
