  ($q$gh03$q$, $q$greetings-hello$q$, 2, $q$Good, or not?$q$, $j$[{"id":"rule-36","type":"rule","title":"Yes/no questions with mái","body":"To make a simple question like \"is it good?\", put mái (high tone) after the word. Answer \"yes\" by repeating the word, or \"no\" by putting mâi (falling tone) before it.","source":"Essential Thai (Higbie), p.23"},{"id":"wi-37","type":"wordIntro","word":{"thai":"ดี","roman":"dii","english":"good"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-47","type":"translationChoice","thai":"ดี","roman":"dii","options":[{"text":"not / no","correct":false},{"text":"hello","correct":false},{"text":"good","correct":true},{"text":"question particle: is it ___?","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ดี"]},{"id":"wi-38","type":"wordIntro","word":{"thai":"มั้ย","roman":"mái","english":"question particle: is it ___?"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-39","type":"translationChoice","thai":"ดีมั้ย","roman":"dii mái","options":[{"text":"Where are you going?","correct":false},{"text":"Is it fun?","correct":false},{"text":"Hello.","correct":false},{"text":"Is it good?","correct":true}],"source":"Essential Thai (Higbie), p.23","parts":["ดี","มั้ย"]},{"id":"so-40","type":"sentenceOrder","prompt":"Is it good?","tileUnit":"word","words":{"a":{"roman":"dii","thai":"ดี"},"b":{"roman":"mái","thai":"มั้ย"},"x0":{"thai":"เพื่อน","roman":"phɯ̂an"},"x1":{"thai":"เที่ยว","roman":"thîao"}},"poolOrder":["x0","x1","a","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.23"},{"id":"sp-41","type":"speak","thai":"ดีมั้ย","roman":"dii mái","meaning":"Is it good?","source":"Essential Thai (Higbie), p.23","parts":["ดี","มั้ย"]},{"id":"wi-42","type":"wordIntro","word":{"thai":"ไม่","roman":"mâi","english":"not / no"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-43","type":"translationChoice","thai":"ไม่ดี","roman":"mâi dii","options":[{"text":"Where are you going?","correct":false},{"text":"No, it's not good.","correct":true},{"text":"Is it good?","correct":false},{"text":"Yes, it's good.","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ไม่","ดี"]},{"id":"so-44","type":"sentenceOrder","prompt":"No, it's not good.","tileUnit":"word","words":{"a":{"roman":"mâi","thai":"ไม่"},"b":{"roman":"dii","thai":"ดี"},"x0":{"thai":"ไป","roman":"pai"},"x1":{"thai":"ไหน","roman":"nǎi"}},"poolOrder":["a","x0","x1","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.23"},{"id":"mc-45","type":"translationChoice","thai":"ไม่","roman":"mâi","options":[{"text":"question particle: is it ___?","correct":false},{"text":"not / no","correct":true},{"text":"good","correct":false},{"text":"hello","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ไม่"]},{"id":"rp-46","type":"reply","context":[{"speaker":"M","thai":"ไปไหน","parts":["ไป","ไหน"],"roman":"pai nǎi","english":"Where did you go?"},{"speaker":"F","thai":"ไปเที่ยว","parts":["ไป","เที่ยว"],"roman":"pai thîao","english":"I went out/traveled around."},{"speaker":"M","thai":"ดีมั้ย","parts":["ดี","มั้ย"],"roman":"dii mái","english":"Was it good?"}],"replySpeaker":"F","thai":"ดี","roman":"dii","english":"Good.","options":[{"thai":"ดี","roman":"dii","correct":true},{"thai":"ไปเที่ยว","roman":"pai thîao","correct":false},{"thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","correct":false},{"thai":"ไม่ดี","roman":"mâi dii","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ดี"]},{"id":"rp-48","type":"reply","context":[{"speaker":"M","thai":"สวัสดีครับ","parts":["สวัสดี","ครับ"],"roman":"sà-wàt-dii khráp","english":"Hello. (said by a man)"},{"speaker":"F","thai":"สวัสดีค่ะ","parts":["สวัสดี","ค่ะ"],"roman":"sà-wàt-dii khâ","english":"Hello. (said by a woman)"},{"speaker":"M","thai":"ดีมั้ย","parts":["ดี","มั้ย"],"roman":"dii mái","english":"Is it good?"}],"replySpeaker":"F","thai":"ไม่ดี","roman":"mâi dii","english":"No, it's not good.","options":[{"thai":"ไม่ดี","roma