  ($q$gh04$q$, $q$greetings-hello$q$, 3, $q$Eating, and going home$q$, $j$[{"id":"wi-51","type":"wordIntro","word":{"thai":"กิน","roman":"gin","english":"eat"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-55","type":"translationChoice","thai":"กิน","roman":"gin","options":[{"text":"good","correct":false},{"text":"where","correct":false},{"text":"go","correct":false},{"text":"eat","correct":true}],"source":"Essential Thai (Higbie), p.22","parts":["กิน"]},{"id":"wi-52","type":"wordIntro","word":{"thai":"ข้าว","roman":"khâao","english":"rice"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-56","type":"translationChoice","thai":"ข้าว","roman":"khâao","options":[{"text":"eat","correct":false},{"text":"rice","correct":true},{"text":"not / no","correct":false},{"text":"go out / travel around","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ข้าว"]},{"id":"so-57","type":"sentenceOrder","prompt":"Eat. (rice/food)","tileUnit":"word","words":{"a":{"roman":"gin","thai":"กิน"},"b":{"roman":"khâao","thai":"ข้าว"},"x0":{"thai":"เที่ยว","roman":"thîao"},"x1":{"thai":"หา","roman":"hǎa"}},"poolOrder":["x0","x1","b","a"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.22"},{"id":"sp-58","type":"speak","thai":"กินข้าว","roman":"gin khâao","meaning":"eat (rice/food)","source":"Essential Thai (Higbie), p.22","parts":["กิน","ข้าว"]},{"id":"so-63","type":"sentenceOrder","prompt":"Go eat.","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"gin","thai":"กิน"},"c":{"roman":"khâao","thai":"ข้าว"},"x0":{"thai":"ดี","roman":"dii"},"x1":{"thai":"หา","roman":"hǎa"}},"poolOrder":["a","x1","b","c","x0"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.22"},{"id":"wi-53","type":"wordIntro","word":{"thai":"กลับ","roman":"glàp","english":"return / go back"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-59","type":"translationChoice","thai":"กลับ","roman":"glàp","options":[{"text":"return / go back","correct":true